window.IELTS.DATA.grammar = [{"quiz":[{"q":"My brother ___ (play) tennis every Saturday.","e":"plays","a":"plays"},{"q":"They ___ (not/watch) TV in the morning.","e":"don\u0027t watch","a":"don\u0027t watch"},{"q":"___ she ___ (live) in Astana?","e":"Does she live","a":"Does she live"},{"q":"The shop ___ (open) at nine.","e":"opens","a":"opens"},{"q":"We usually ___ (have) lunch at school.","e":"have","a":"have"},{"q":"He ___ (not/like) fish.","e":"doesn\u0027t like","a":"doesn\u0027t like"}],"forms":["(+) I/you/we/they + V | he/she/it + V-s","(-) I/you/we/they + do not (don\u0027t) + V | he/she/it + does not (doesn\u0027t) + V","(?) Do + I/you/we/they + V? | Does + he/she/it + V?"],"takeaway":"Use Present Simple for habits, routines, facts and schedules.","rules":["Use Present Simple for habits, routines, facts and schedules.","Add -s/-es to the verb with he, she, it (works - he works; watches - she watches; studies - it studies).","Signal words: always, usually, often, sometimes, never, every day, on Mondays."],"notes":["After does/doesn\u0027t the verb has no -s: She doesn\u0027t work (not \"doesn\u0027t works\")."],"level":"A1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["I get up at 7 o\u0027clock every day.","She doesn\u0027t like coffee.","Does he play football on Sundays? - Yes, he does.","The Earth goes round the Sun."],"title":"Present Simple"},{"quiz":[{"q":"I ___ (watch) a film yesterday.","e":"watched","a":"watched"},{"q":"She ___ (go) to the park last week.","e":"went","a":"went"},{"q":"They ___ (not/play) football on Monday.","e":"didn\u0027t play","a":"didn\u0027t play"},{"q":"___ you ___ (see) Ali yesterday?","e":"Did you see","a":"Did you see"},{"q":"He ___ (have) breakfast at 8.","e":"had","a":"had"},{"q":"We ___ (not/be) at home last night.","e":"weren\u0027t","a":"weren\u0027t"}],"forms":["(+) Subject + V2 (worked / went)","(-) Subject + did not (didn\u0027t) + V1","(?) Did + subject + V1?"],"takeaway":"Use Past Simple for finished actions in the past (yesterday, last week, in 2020, two days ago).","rules":["Use Past Simple for finished actions in the past (yesterday, last week, in 2020, two days ago).","Regular verbs add -ed (work - worked; stop - stopped; study - studied). Irregular verbs have their own form (go - went, see - saw, have - had)."],"notes":["After did/didn\u0027t use the base verb: Did he go? (not \"Did he went?\")."],"level":"A1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["We visited our grandmother last Sunday.","She went to school by bus.","I didn\u0027t see him yesterday.","Did you finish your homework? - Yes, I did."],"title":"Past Simple"},{"quiz":[{"q":"Tomorrow I ___ (visit) my friend.","e":"will visit","a":"will visit"},{"q":"She ___ (not/be) at school on Friday.","e":"won\u0027t be","a":"won\u0027t be"},{"q":"___ it ___ (snow) next week?","e":"Will it snow","a":"Will it snow"},{"q":"I think they ___ (win) the match.","e":"will win","a":"will win"},{"q":"We ___ (travel) to Almaty next month.","e":"will travel","a":"will travel"},{"q":"He ___ (not/forget) your birthday.","e":"won\u0027t forget","a":"won\u0027t forget"}],"forms":["(+) Subject + will + V","(-) Subject + will not (won\u0027t) + V","(?) Will + subject + V?"],"takeaway":"Use will + verb for decisions made at the moment of speaking, predictions and promises.","rules":["Use will + verb for decisions made at the moment of speaking, predictions and promises.","Signal words: tomorrow, next week, soon, in 2030, I think, probably."],"notes":["Short form: I\u0027ll, you\u0027ll, he\u0027ll, she\u0027ll, we\u0027ll, they\u0027ll."],"level":"A1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["I will call you tomorrow.","It will rain this evening.","I won\u0027t be late, I promise.","Will she come to the party? - Yes, she will."],"title":"Future Simple"},{"quiz":[{"q":"14","e":"fourteen","a":"fourteen"},{"q":"40","e":"forty","a":"forty"},{"q":"67","e":"sixty-seven","a":"sixty-seven"},{"q":"105","e":"one hundred and five","a":"one hundred and five"},{"q":"1,200","e":"one thousand two hundred","a":"one thousand two hundred"},{"q":"15 and 50: which one ends in -teen?","e":"15 (fifteen)","a":["15 (fifteen)","15","15 fifteen"]}],"forms":["21 = twenty-one | 340 = three hundred and forty | 2,500 = two thousand five hundred"],"takeaway":"Cardinal numbers show quantity: one, two, three ... twelve, thirteen ... nineteen, twenty, thirty ... ninety, a hundred, a thousand.","rules":["Cardinal numbers show quantity: one, two, three ... twelve, thirteen ... nineteen, twenty, thirty ... ninety, a hundred, a thousand.","Numbers 13-19 end in -teen (stress on -teen); tens end in -ty (thirty, forty, fifty).","Write compound numbers with a hyphen from 21 to 99: twenty-one, sixty-five.","Say \"and\" after hundred in British English: 215 = two hundred and fifteen."],"notes":["Hundred, thousand and million have no -s after a number: three hundred (not \"three hundreds\")."],"level":"A1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["There are thirty students in our class.","My phone costs two hundred and fifty dollars.","The year 2024 is read: twenty twenty-four."],"title":"Numerals"},{"quiz":[{"q":"Listen! Someone ___ (sing).","e":"is singing","a":"is singing"},{"q":"We ___ (not/watch) TV now.","e":"aren\u0027t watching","a":"aren\u0027t watching"},{"q":"___ you ___ (do) your homework?","e":"Are you doing","a":"Are you doing"},{"q":"He ___ (write) a letter at the moment.","e":"is writing","a":"is writing"},{"q":"The children ___ (run) in the park.","e":"are running","a":"are running"},{"q":"I ___ (not/sit) at my desk.","e":"am not sitting","a":"am not sitting"}],"forms":["(+) Subject + am/is/are + V-ing","(-) Subject + am/is/are + not + V-ing","(?) Am/Is/Are + subject + V-ing?"],"takeaway":"Use Present Continuous for actions happening now, around now, and for fixed plans in the near future.","rules":["Use Present Continuous for actions happening now, around now, and for fixed plans in the near future.","Signal words: now, at the moment, right now, today, look!, listen!"],"notes":["Spelling: run - running, sit - sitting, make - making, lie - lying."],"level":"A1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["I am reading a book now.","She is not sleeping, she is cooking.","Are they playing in the yard?","Look! It is raining."],"title":"Present Continuous"},{"quiz":[{"q":"1st","e":"first","a":"first"},{"q":"2nd","e":"second","a":"second"},{"q":"5th","e":"fifth","a":"fifth"},{"q":"12th","e":"twelfth","a":"twelfth"},{"q":"20th","e":"twentieth","a":"twentieth"},{"q":"Write in words: 31st","e":"thirty-first","a":"thirty-first"}],"forms":["1st first | 2nd second | 3rd third | 5th fifth | 9th ninth | 12th twelfth | 21st twenty-first"],"takeaway":"Ordinal numbers show order: first, second, third, fourth, fifth ...","rules":["Ordinal numbers show order: first, second, third, fourth, fifth ...","Most ordinals = number + -th (fourth, sixth, tenth). Exceptions: first, second, third, fifth (fi-f-th), eighth, ninth, twelfth.","For tens, y changes to ie: twenty - twentieth, thirty - thirtieth.","Use the before ordinals: the first day, the third floor."],"notes":["Dates: 3 March = the third of March."],"level":"A1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["My birthday is on the fifth of May.","She lives on the ninth floor.","This is my second English lesson today."],"title":"Ordinal numbers"},{"quiz":[{"q":"___ is my friend. (Aigerim)","e":"She","a":"She"},{"q":"I can see ___ . (Tom and Ali)","e":"them","a":"them"},{"q":"Please help ___ . (I)","e":"me","a":"me"},{"q":"Peter is tall. ___ is a basketball player.","e":"He","a":"He"},{"q":"Mum calls ___ every evening. (we)","e":"us","a":"us"},{"q":"Where is the dog? I can\u0027t find ___ .","e":"it","a":"it"}],"forms":["I - me | you - you | he - him | she - her | it - it | we - us | they - them"],"takeaway":"Subject pronouns (do the action): I, you, he, she, it, we, they.","rules":["Subject pronouns (do the action): I, you, he, she, it, we, they.","Object pronouns (receive the action): me, you, him, her, it, us, them.","Use he for a man, she for a woman, it for things and animals, they for plural."],"notes":["Subject pronoun goes before the verb, object pronoun goes after it."],"level":"A1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["She is my sister. I love her.","They live in Astana. We often visit them.","Give me the book, please."],"title":"Personal pronouns"},{"quiz":[{"q":"I have ___ orange.","e":"an","a":"an"},{"q":"___ sun is hot today.","e":"The","a":"The"},{"q":"He is ___ doctor.","e":"a","a":"a"},{"q":"Can you close ___ window, please? (one window in the room)","e":"the","a":"the"},{"q":"She wants ___ umbrella.","e":"an","a":"an"},{"q":"I like ___ music. (in general)","e":"(no article)","a":["(no article)","","no article"]}],"forms":["a + consonant sound | an + vowel sound | the = specific / known"],"takeaway":"a / an are used with singular countable nouns when we mention something for the first time or say what it is.","rules":["a / an are used with singular countable nouns when we mention something for the first time or say what it is.","Use an before vowel sounds (an apple, an hour); a before consonant sounds (a book, a university).","Use the when the thing is known or unique (the sun, the teacher), and with superlatives.","No article with plural nouns in general (Dogs are friendly), languages, most countries and meals."],"notes":["Pronunciation matters: a university /ju:/, an hour (silent h)."],"level":"A1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["I have a dog. The dog is black.","She is an engineer.","The moon is bright tonight.","We have breakfast at eight. (no article)"],"title":"Articles"},{"quiz":[{"q":"___ a cat on the sofa.","e":"There is","a":"There is"},{"q":"___ two books on the table.","e":"There are","a":"There are"},{"q":"___ there any bread?","e":"Is","a":"Is"},{"q":"There ___ (not) any students in the classroom.","e":"aren\u0027t","a":"aren\u0027t"},{"q":"___ there a bank here?","e":"Is","a":"Is"},{"q":"There ___ some apples in the bag.","e":"are","a":"are"}],"forms":["(+) There is a / There are two","(-) There isn\u0027t a / There aren\u0027t any","(?) Is there a ...? / Are there any ...?"],"takeaway":"Use there is/there are to say that something exists or is in a place.","rules":["Use there is/there are to say that something exists or is in a place.","There is + singular or uncountable noun; there are + plural noun."],"notes":["Use some in positive sentences and any in negatives and questions."],"level":"A2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["There is a park near my house.","There are three chairs in the room.","Is there any milk in the fridge? - No, there isn\u0027t."],"title":"There is/There are"},{"quiz":[{"q":"This is ___ (I) book.","e":"my","a":"my"},{"q":"That bag is ___ (she).","e":"hers","a":"hers"},{"q":"___ (they) car is new.","e":"Their","a":"Their"},{"q":"The red pen is ___ (I).","e":"mine","a":"mine"},{"q":"Where is ___ (you) phone?","e":"your","a":"your"},{"q":"Our teacher is nice. ___ (they) is nice too.","e":"Theirs","a":"Theirs"}],"forms":["my book - mine | your book - yours | her book - hers | our book - ours | their book - theirs"],"takeaway":"Possessive adjectives go before a noun: my, your, his, her, its, our, their.","rules":["Possessive adjectives go before a noun: my, your, his, her, its, our, their.","Possessive pronouns stand alone (no noun after them): mine, yours, his, hers, ours, theirs."],"notes":["There is no apostrophe: yours, hers, its (not \"your\u0027s\")."],"level":"A2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["This is my pen. This pen is mine.","Is that her bag? - No, it\u0027s his.","Their house is bigger than ours."],"title":"Possessive pronouns"},{"quiz":[{"q":"___ the door, please. (close)","e":"Close","a":"Close"},{"q":"___ late for school! (not/be)","e":"Don\u0027t be","a":"Don\u0027t be"},{"q":"___ to the park. (go, suggestion)","e":"Let\u0027s go","a":"Let\u0027s go"},{"q":"___ in class. (not/eat)","e":"Don\u0027t eat","a":"Don\u0027t eat"},{"q":"___ your name here. (write)","e":"Write","a":"Write"},{"q":"___ me, please. (help)","e":"Help","a":"Help"}],"forms":["(+) V! | (-) Don\u0027t + V! | Suggestion: Let\u0027s + V"],"takeaway":"Use the imperative for orders, instructions, advice and requests.","rules":["Use the imperative for orders, instructions, advice and requests.","The form is the base verb without a subject. Add please to be polite.","For negatives use Don\u0027t + verb. For \"let\u0027s\" suggestions use Let\u0027s + verb."],"notes":["Be careful! Be quiet! Don\u0027t be late!"],"level":"A2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["Open your books, please.","Don\u0027t run in the corridor.","Let\u0027s play chess after school."],"title":"Imperative mood"},{"quiz":[{"q":"She ___ (visit) her aunt on Sunday.","e":"is going to visit","a":"is going to visit"},{"q":"We ___ (not/buy) a new car.","e":"aren\u0027t going to buy","a":"aren\u0027t going to buy"},{"q":"___ you ___ (watch) the match?","e":"Are you going to watch","a":"Are you going to watch"},{"q":"Look! The boy ___ (fall).","e":"is going to fall","a":"is going to fall"},{"q":"I ___ (cook) dinner tonight.","e":"am going to cook","a":"am going to cook"},{"q":"They ___ (not/come) to the party.","e":"aren\u0027t going to come","a":"aren\u0027t going to come"}],"forms":["(+) Subject + am/is/are + going to + V","(-) Subject + am/is/are + not + going to + V","(?) Am/Is/Are + subject + going to + V?"],"takeaway":"Use be going to for plans and intentions, and for predictions based on evidence.","rules":["Use be going to for plans and intentions, and for predictions based on evidence."],"notes":["Will is for sudden decisions; going to is for plans made before."],"level":"A2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["I am going to study medicine.","Look at the clouds! It is going to rain.","Are you going to visit your cousin this weekend?"],"title":"To be going to"},{"quiz":[{"q":"___ you tired?","e":"Are","a":"Are"},{"q":"___ he like pizza?","e":"Does","a":"Does"},{"q":"___ they go to school yesterday?","e":"Did","a":"Did"},{"q":"___ your mother cook well?","e":"Does","a":"Does"},{"q":"___ you swim?","e":"Can","a":"Can"},{"q":"Make a question: She is a nurse.","e":"Is she a nurse?","a":"Is she a nurse?"}],"forms":["Am/Is/Are + subject ...? | Can/Must + subject + V? | Do/Does/Did + subject + V?"],"takeaway":"General (yes/no) questions are answered with yes or no.","rules":["General (yes/no) questions are answered with yes or no.","With to be, modal verbs and have in perfect tenses, put the verb before the subject. In other cases use do/does/did."],"notes":["Short answers repeat the auxiliary: Yes, I do. No, she isn\u0027t."],"level":"A2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["Are you a student? - Yes, I am.","Can she swim? - No, she can\u0027t.","Do they live here? - Yes, they do.","Did he call you? - No, he didn\u0027t."],"title":"General questions"},{"quiz":[{"q":"He ___ (can) play the piano.","e":"can","a":"can"},{"q":"When I was a child, I ___ swim. (could)","e":"could","a":"could"},{"q":"___ I use your pen?","e":"Can","a":"Can"},{"q":"___ you help me, please? (polite)","e":"Could","a":"Could"},{"q":"She ___ speak Chinese. (not)","e":"can\u0027t","a":"can\u0027t"},{"q":"They ___ run fast. (can)","e":"can","a":"can"}],"forms":["(+) Subject + can/could + V | (-) cannot (can\u0027t) / could not (couldn\u0027t) | (?) Can/Could + subject + V?"],"takeaway":"Can shows ability, permission and possibility in the present. Could is the past of can and is also a polite request.","rules":["Can shows ability, permission and possibility in the present. Could is the past of can and is also a polite request.","Modal verbs have no -s in the third person and no do/does: She can swim. Can she swim?"],"notes":["Can has no future or infinitive: use will be able to."],"level":"A2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["I can speak English and Russian.","When I was five I could ride a bike.","Could you open the window, please?","She can\u0027t come today."],"title":"Modal Verbs (Can/Could)"},{"quiz":[{"q":"Water ___ (boil) at 100 degrees.","e":"boils","a":"boils"},{"q":"Be quiet! The baby ___ (sleep).","e":"is sleeping","a":"is sleeping"},{"q":"I ___ (go) to the gym on Fridays.","e":"go","a":"go"},{"q":"Where is Dan? He ___ (cook) now.","e":"is cooking","a":"is cooking"},{"q":"She ___ (not/want) tea.","e":"doesn\u0027t want","a":"doesn\u0027t want"},{"q":"Today they ___ (wear) uniforms.","e":"are wearing","a":"are wearing"}],"forms":["Simple: V / V-s | Continuous: am/is/are + V-ing"],"takeaway":"Present Simple = habits, routines, facts (every day, usually). Present Continuous = action happening now (now, at the moment).","rules":["Present Simple = habits, routines, facts (every day, usually). Present Continuous = action happening now (now, at the moment).","Some verbs are rarely used in continuous: like, love, know, want, need, understand."],"notes":["Compare: He plays football (every week) / He is playing football (now)."],"level":"A2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["She usually drinks tea, but today she is drinking coffee.","I go to school by bus, but now I am walking.","I know the answer. (not \"I am knowing\")"],"title":"Present Simple vs Present Continuous"},{"quiz":[{"q":"Look! He ___ (run) very fast.","e":"is running","a":"is running"},{"q":"My sister ___ (study) every evening.","e":"studies","a":"studies"},{"q":"I think it ___ (rain) tomorrow.","e":"will rain","a":"will rain"},{"q":"We ___ (have) a test on Monday. (fixed plan)","e":"are having","a":"are having"},{"q":"The shop ___ (close) at 8 p.m.","e":"closes","a":"closes"},{"q":"Wait, I ___ (help) you. (decision now)","e":"will help","a":"will help"}],"forms":["V/V-s | am/is/are + V-ing | will + V"],"takeaway":"Present Simple: habits and schedules. Present Continuous: now and arranged plans. Future Simple: decisions at the moment, predictions, promises.","rules":["Present Simple: habits and schedules. Present Continuous: now and arranged plans. Future Simple: decisions at the moment, predictions, promises.","Choose the tense by the signal word: usually - Simple; now - Continuous; tomorrow/probably - Future Simple."],"notes":["A train timetable can use Present Simple: The train leaves at 6."],"level":"A2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["I usually walk to work. (habit)","I am walking to work now. (action now)","I will walk to work tomorrow. (decision/plan)"],"title":"Present Cont. vs. Present Simple vs. Future Simple"},{"quiz":[{"q":"At 9 p.m. she ___ (read) a book.","e":"was reading","a":"was reading"},{"q":"I ___ (cross) the street when I saw Ali.","e":"was crossing","a":"was crossing"},{"q":"They ___ (not/sleep) at midnight.","e":"weren\u0027t sleeping","a":"weren\u0027t sleeping"},{"q":"What ___ you ___ (do) at six?","e":"were you doing","a":"were you doing"},{"q":"While he ___ (cook), the phone rang.","e":"was cooking","a":"was cooking"},{"q":"We ___ (watch) TV when the lights went out.","e":"were watching","a":"were watching"}],"forms":["(+) Subject + was/were + V-ing | (-) wasn\u0027t/weren\u0027t + V-ing | (?) Was/Were + subject + V-ing?"],"takeaway":"Use Past Continuous for an action in progress at a specific moment in the past, or for a longer action interrupted by a shorter one.","rules":["Use Past Continuous for an action in progress at a specific moment in the past, or for a longer action interrupted by a shorter one."],"notes":["when + Past Simple (short action); while + Past Continuous (long action)."],"level":"B1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["At 8 o\u0027clock yesterday I was having breakfast.","I was walking home when it started to rain.","They were playing chess while we were cooking."],"title":"Past Continuous"},{"quiz":[{"q":"I ___ (see) this film three times.","e":"have seen","a":"have seen"},{"q":"She ___ (not/finish) yet.","e":"hasn\u0027t finished","a":"hasn\u0027t finished"},{"q":"___ you ever ___ (be) to London?","e":"Have you ever been","a":"Have you ever been"},{"q":"They ___ (live) here for ten years.","e":"have lived","a":"have lived"},{"q":"He ___ (just/arrive).","e":"has just arrived","a":"has just arrived"},{"q":"We ___ (know) her since 2020.","e":"have known","a":"have known"}],"forms":["(+) Subject + have/has + V3 | (-) haven\u0027t/hasn\u0027t + V3 | (?) Have/Has + subject + V3?"],"takeaway":"Use Present Perfect for experiences, results that are important now, and actions that started in the past and continue to now.","rules":["Use Present Perfect for experiences, results that are important now, and actions that started in the past and continue to now.","Signal words: ever, never, already, yet, just, recently, so far, for, since."],"notes":["For + period (for two years); since + starting point (since Monday)."],"level":"B1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["I have visited Turkey twice.","She has just finished her homework.","Have you ever eaten sushi?","We have lived here since 2019."],"title":"Present Perfect"},{"quiz":[{"q":"When we came, the bus ___ (leave).","e":"had left","a":"had left"},{"q":"She ___ (not/eat) before the exam.","e":"hadn\u0027t eaten","a":"hadn\u0027t eaten"},{"q":"By 5 o\u0027clock he ___ (finish) the report.","e":"had finished","a":"had finished"},{"q":"I ___ (already/see) the film, so I stayed home.","e":"had already seen","a":"had already seen"},{"q":"___ they ___ (arrive) before the lesson began?","e":"Had they arrived","a":"Had they arrived"},{"q":"After he ___ (do) his homework, he went out.","e":"had done","a":"had done"}],"forms":["(+) Subject + had + V3 | (-) hadn\u0027t + V3 | (?) Had + subject + V3?"],"takeaway":"Use Past Perfect for an action completed before another action or time in the past.","rules":["Use Past Perfect for an action completed before another action or time in the past."],"notes":["Common signal words: before, after, by the time, already, when."],"level":"B1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["When I arrived, the film had already started.","She had finished her work before he called.","Had they left before you came?"],"title":"Past Perfect"},{"quiz":[{"q":"She promised she ___ (help) us.","e":"would help","a":"would help"},{"q":"I thought it ___ (rain).","e":"would rain","a":"would rain"},{"q":"He said he ___ (not/be) late.","e":"wouldn\u0027t be","a":"wouldn\u0027t be"},{"q":"They knew we ___ (come) soon.","e":"would come","a":"would come"},{"q":"She said she ___ (visit) us next week.","e":"would visit","a":"would visit"},{"q":"I hoped he ___ (pass) the exam.","e":"would pass","a":"would pass"}],"forms":["Subject + would + V | was/were going to + V"],"takeaway":"Use Future in the Past (would + verb) to talk about the future from a past point of view, mostly in reported speech.","rules":["Use Future in the Past (would + verb) to talk about the future from a past point of view, mostly in reported speech."],"notes":["Sequence of tenses: will becomes would after a past reporting verb."],"level":"B1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["He said he would call me later.","I knew that she would win.","They told us they were going to move."],"title":"Future in the Past"},{"quiz":[{"q":"Milk ___ (sell) in this shop.","e":"is sold","a":"is sold"},{"q":"Many books ___ (read) by students.","e":"are read","a":"are read"},{"q":"The window ___ (open) every morning.","e":"is opened","a":"is opened"},{"q":"Football ___ (play) in many countries.","e":"is played","a":"is played"},{"q":"The tests ___ (check) by the teacher.","e":"are checked","a":"are checked"},{"q":"Rice ___ (grow) in Asia.","e":"is grown","a":"is grown"}],"forms":["am/is/are + V3 (+ by agent)"],"takeaway":"Use the passive when the action is more important than who does it.","rules":["Use the passive when the action is more important than who does it."],"notes":["Active: They make cars here. Passive: Cars are made here."],"level":"B1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["English is spoken all over the world.","The rooms are cleaned every day.","The letter is written by my mother."],"title":"Passive Voice - Present Simple"},{"quiz":[{"q":"They ___ (play) for two hours.","e":"have been playing","a":"have been playing"},{"q":"She ___ (work) here since 2018.","e":"has been working","a":"has been working"},{"q":"How long ___ you ___ (wait)?","e":"have you been waiting","a":"have you been waiting"},{"q":"It ___ (rain) all day.","e":"has been raining","a":"has been raining"},{"q":"We ___ (learn) French for a year.","e":"have been learning","a":"have been learning"},{"q":"He ___ (not/sleep) well lately.","e":"hasn\u0027t been sleeping","a":"hasn\u0027t been sleeping"}],"forms":["Subject + have/has + been + V-ing"],"takeaway":"Use it for actions that started in the past and are still going on, or just stopped with a visible result; it stresses the duration.","rules":["Use it for actions that started in the past and are still going on, or just stopped with a visible result; it stresses the duration."],"notes":["Not used with state verbs: I have known him for years (not \"have been knowing\")."],"level":"B1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["I have been studying English for three years.","She has been waiting since 5 o\u0027clock.","Why are your hands dirty? - I have been working in the garden."],"title":"Present Perfect Continuous"},{"quiz":[{"q":"She sings ___ (beautiful).","e":"beautifully","a":"beautifully"},{"q":"He drives very ___ (fast/fastly).","e":"fast","a":"fast"},{"q":"The boy is a ___ (good) player; he plays ___.","e":"well","a":"well"},{"q":"Please speak ___ (slow).","e":"slowly","a":"slowly"},{"q":"I ___ (never) eat fish.","e":"never eat","a":"never eat"},{"q":"They ___ (usually) are on time.","e":"are usually","a":"are usually"}],"forms":["adjective + -ly | y - ily (happy - happily)"],"takeaway":"Adverbs describe verbs, adjectives or other adverbs. Many are formed with adjective + -ly (slow - slowly).","rules":["Adverbs describe verbs, adjectives or other adverbs. Many are formed with adjective + -ly (slow - slowly).","Irregular adverbs: good - well, fast - fast, hard - hard, late - late.","Frequency adverbs (always, usually, often, sometimes, never) go before the main verb but after to be."],"notes":["Hardly = almost not; hard = with effort."],"level":"B1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["She speaks English fluently.","He works hard.","They are always late."],"title":"Adverbs"},{"quiz":[{"q":"The Eiffel Tower ___ (build) in 1889.","e":"was built","a":"was built"},{"q":"These cars ___ (make) in Germany.","e":"were made","a":"were made"},{"q":"The thief ___ (catch) yesterday.","e":"was caught","a":"was caught"},{"q":"The books ___ (not/return).","e":"weren\u0027t returned","a":"weren\u0027t returned"},{"q":"___ the letter ___ (send)?","e":"Was the letter sent","a":"Was the letter sent"},{"q":"The film ___ (watch) by millions.","e":"was watched","a":"was watched"}],"forms":["was/were + V3"],"takeaway":"Use the Past Simple passive for finished actions in the past when the doer is unknown or unimportant.","rules":["Use the Past Simple passive for finished actions in the past when the doer is unknown or unimportant."],"notes":["Active: Alikhan wrote this poem. Passive: This poem was written by Alikhan."],"level":"B1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["The bridge was built in 1998.","The windows were broken last night.","Where were you born?"],"title":"Passive Voice - Past Simple"},{"quiz":[{"q":"When I arrived, the train ___ (already/leave).","e":"had already left","a":"had already left"},{"q":"I ___ (open) the door and ___ (go) in.","e":"opened, went","a":"opened, went"},{"q":"He was tired because he ___ (work) all day.","e":"had worked","a":"had worked"},{"q":"After she ___ (eat), she went to bed.","e":"had eaten","a":"had eaten"},{"q":"I ___ (meet) him yesterday.","e":"met","a":"met"},{"q":"They ___ (not/finish) when the teacher came.","e":"hadn\u0027t finished","a":"hadn\u0027t finished"}],"forms":["V2 | had + V3"],"takeaway":"Past Simple: events in order. Past Perfect: the earlier of two past events.","rules":["Past Simple: events in order. Past Perfect: the earlier of two past events."],"notes":["Use Past Perfect only when the order of events needs to be clear."],"level":"B1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["I came home and cooked dinner. (first came, then cooked)","When I came home, my mother had cooked dinner. (cooked first)","She said she had seen him."],"title":"Past Simple vs. Past Perfect"},{"quiz":[{"q":"I ___ (write) three emails today.","e":"have written","a":"have written"},{"q":"I ___ (write) emails for two hours.","e":"have been writing","a":"have been writing"},{"q":"How many pages ___ you ___ (read)?","e":"have you read","a":"have you read"},{"q":"How long ___ she ___ (study)?","e":"has she been studying","a":"has she been studying"},{"q":"He ___ (clean) the car. It\u0027s shiny now.","e":"has cleaned","a":"has cleaned"},{"q":"They ___ (run) for an hour.","e":"have been running","a":"have been running"}],"forms":["have/has + V3 | have/has + been + V-ing"],"takeaway":"Present Perfect focuses on the result or number of times. Present Perfect Continuous focuses on the process and duration.","rules":["Present Perfect focuses on the result or number of times. Present Perfect Continuous focuses on the process and duration."],"notes":["How many/How much - Present Perfect; How long - Present Perfect Continuous."],"level":"B1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["I have painted the room. (it is finished)","I have been painting the room all day. (the process)","She has read 5 books this month. / She has been reading all evening."],"title":"Present Perfect vs. Present Perfect Continuous"},{"quiz":[{"q":"He ___ (sleep) now.","e":"is sleeping","a":"is sleeping"},{"q":"He ___ (sleep) for ten hours.","e":"has been sleeping","a":"has been sleeping"},{"q":"They ___ (talk) on the phone since noon.","e":"have been talking","a":"have been talking"},{"q":"I ___ (read) a book at the moment.","e":"am reading","a":"am reading"},{"q":"How long ___ you ___ (live) here?","e":"have you been living","a":"have you been living"},{"q":"We ___ (work) now, don\u0027t call us.","e":"are working","a":"are working"}],"forms":["am/is/are + V-ing | have/has been + V-ing"],"takeaway":"Present Continuous: action in progress now. Present Perfect Continuous: the action began earlier and its duration up to now is important.","rules":["Present Continuous: action in progress now. Present Perfect Continuous: the action began earlier and its duration up to now is important."],"notes":["With for/since/how long choose Present Perfect Continuous."],"level":"B1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["I am waiting for the bus.","I have been waiting for the bus for twenty minutes.","She is learning Spanish. / She has been learning Spanish since January."],"title":"Present Continuous vs. Present Perfect Continuous"},{"quiz":[{"q":"The report ___ (send) tomorrow.","e":"will be sent","a":"will be sent"},{"q":"The room ___ (clean) later.","e":"will be cleaned","a":"will be cleaned"},{"q":"The tickets ___ (not/sell) after Friday.","e":"won\u0027t be sold","a":"won\u0027t be sold"},{"q":"___ the winner ___ (announce) soon?","e":"Will the winner be announced","a":"Will the winner be announced"},{"q":"A new road ___ (build) next year.","e":"will be built","a":"will be built"},{"q":"The goods ___ (deliver) in a week.","e":"will be delivered","a":"will be delivered"}],"forms":["will be + V3"],"takeaway":"Use the Future Simple passive for actions that will be done to someone or something.","rules":["Use the Future Simple passive for actions that will be done to someone or something."],"notes":["Active: They will open the museum in May. Passive: The museum will be opened in May."],"level":"B1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["The results will be announced tomorrow.","A new school will be built here.","The work won\u0027t be finished today."],"title":"Passive Voice - Future Simple"},{"quiz":[{"q":"The homework ___ (do).","e":"has been done","a":"has been done"},{"q":"These letters ___ (not/send) yet.","e":"haven\u0027t been sent","a":"haven\u0027t been sent"},{"q":"___ the work ___ (finish)?","e":"Has the work been finished","a":"Has the work been finished"},{"q":"My phone ___ (steal).","e":"has been stolen","a":"has been stolen"},{"q":"The shops ___ (close).","e":"have been closed","a":"have been closed"},{"q":"The cake ___ (eat).","e":"has been eaten","a":"has been eaten"}],"forms":["have/has been + V3"],"takeaway":"Use the Present Perfect passive for a result that matters now when the doer is not important.","rules":["Use the Present Perfect passive for a result that matters now when the doer is not important."],"notes":["Active: Someone has cleaned the room. Passive: The room has been cleaned."],"level":"B1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["The window has been broken.","My bike has been stolen.","Dinner has just been served."],"title":"Passive Voice - Present Perfect"},{"quiz":[{"q":"___ is your birthday? (date)","e":"When","a":"When"},{"q":"___ do you go to school? (reason: why)","e":"Why","a":"Why"},{"q":"___ books do you have?","e":"How many","a":"How many"},{"q":"___ phone is this? (owner)","e":"Whose","a":"Whose"},{"q":"___ opened the door? (a person)","e":"Who","a":"Who"},{"q":"___ did he go last summer? (place)","e":"Where","a":"Where"}],"forms":["Wh-word + do/does/did + subject + V?"],"takeaway":"Wh-questions ask for information: what, who, whom, whose, where, when, why, which, how.","rules":["Wh-questions ask for information: what, who, whom, whose, where, when, why, which, how.","Word order: question word + auxiliary + subject + verb. If who/what is the subject, no auxiliary is used."],"notes":["How many + plural; how much + uncountable."],"level":"B1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["Where do you live?","What did she buy yesterday?","Who called you? (who is the subject)","How long have you been here?"],"title":"Wh-questions"},{"quiz":[{"q":"I ___ (visit) Paris in 2019.","e":"visited","a":"visited"},{"q":"I ___ (visit) Paris twice.","e":"have visited","a":"have visited"},{"q":"She ___ (finish) her work an hour ago.","e":"finished","a":"finished"},{"q":"___ you ever ___ (try) sushi?","e":"Have you ever tried","a":"Have you ever tried"},{"q":"When ___ he ___ (arrive)?","e":"did he arrive","a":"did he arrive"},{"q":"They ___ (already/eat).","e":"have already eaten","a":"have already eaten"}],"forms":["V2 (with time) | have/has + V3 (without time)"],"takeaway":"Past Simple: a finished time in the past (yesterday, in 2010). Present Perfect: no exact time, a link to the present.","rules":["Past Simple: a finished time in the past (yesterday, in 2010). Present Perfect: no exact time, a link to the present."],"notes":["Never use Present Perfect with yesterday, last year, ago."],"level":"B2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["I saw this film yesterday.","I have seen this film.","She lost her key. / She has lost her key (she doesn\u0027t have it now)."],"title":"Present Perfect vs Past Simple"},{"quiz":[{"q":"I ___ (sleep) when the phone ___ (ring).","e":"was sleeping, rang","a":"was sleeping, rang"},{"q":"He ___ (open) the door and ___ (enter).","e":"opened, entered","a":"opened, entered"},{"q":"They ___ (play) when it ___ (start) to rain.","e":"were playing, started","a":"were playing, started"},{"q":"What ___ you ___ (do) at 10 p.m.?","e":"were you doing","a":"were you doing"},{"q":"She ___ (fall) while she ___ (run).","e":"fell, was running","a":"fell, was running"},{"q":"We ___ (visit) the museum last week.","e":"visited","a":"visited"}],"forms":["V2 | was/were + V-ing"],"takeaway":"Past Simple: finished actions, one after another. Past Continuous: an action in progress; background for another action.","rules":["Past Simple: finished actions, one after another. Past Continuous: an action in progress; background for another action."],"notes":["Long action in the background - Past Continuous; short event - Past Simple."],"level":"B2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["I was reading when he called.","She took a shower and went to bed.","At 7 p.m. we were having dinner."],"title":"Past Simple vs. Past Continuous"},{"quiz":[{"q":"My bag is ___ (heavy) than yours.","e":"heavier","a":"heavier"},{"q":"This test is ___ (difficult) than the last one.","e":"more difficult","a":"more difficult"},{"q":"She is ___ (good) at maths than me.","e":"better","a":"better"},{"q":"Today is ___ (hot) than yesterday.","e":"hotter","a":"hotter"},{"q":"English is ___ (easy) than Chinese.","e":"easier","a":"easier"},{"q":"This film is ___ (bad) than that one.","e":"worse","a":"worse"}],"forms":["adj-er + than | more + adj + than | as + adj + as"],"takeaway":"Use the comparative to compare two things.","rules":["Use the comparative to compare two things.","Short adjectives: + -er (tall - taller; big - bigger; happy - happier). Long adjectives: more + adjective (more interesting).","Irregular: good - better, bad - worse, far - farther/further."],"notes":["Do not use more with -er: not \"more taller\"."],"level":"B2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["Astana is colder than Almaty.","This book is more interesting than that one.","He is as tall as his brother."],"title":"Comparative degree of adjectives"},{"quiz":[{"q":"He is ___ (tall) boy in the team.","e":"the tallest","a":"the tallest"},{"q":"This is ___ (beautiful) place I know.","e":"the most beautiful","a":"the most beautiful"},{"q":"She is ___ (good) singer.","e":"the best","a":"the best"},{"q":"It was ___ (bad) film.","e":"the worst","a":"the worst"},{"q":"Baikal is ___ (deep) lake.","e":"the deepest","a":"the deepest"},{"q":"That is ___ (expensive) car.","e":"the most expensive","a":"the most expensive"}],"forms":["the + adj-est | the most + adj"],"takeaway":"Use the superlative to compare one thing with a group. Always use the.","rules":["Use the superlative to compare one thing with a group. Always use the.","Short adjectives: the + -est (the tallest). Long adjectives: the most + adjective. Irregular: the best, the worst, the farthest."],"notes":["Use in with places/groups: the best in the class."],"level":"B2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["Everest is the highest mountain in the world.","She is the most talented student in our class.","This is the worst day of my life."],"title":"Superlative degree of adjectives"},{"quiz":[{"q":"We ___ (live) in a village.","e":"used to live","a":"used to live"},{"q":"He ___ (not/smoke).","e":"didn\u0027t use to smoke","a":"didn\u0027t use to smoke"},{"q":"___ you ___ (play) chess as a child?","e":"Did you use to play","a":"Did you use to play"},{"q":"She ___ (be) shy.","e":"used to be","a":"used to be"},{"q":"They ___ (go) fishing every summer.","e":"used to go","a":"used to go"},{"q":"I ___ (not/like) vegetables.","e":"didn\u0027t use to like","a":"didn\u0027t use to like"}],"forms":["(+) used to + V | (-) didn\u0027t use to + V | (?) Did ... use to + V?"],"takeaway":"Use used to + verb for past habits or states that are no longer true.","rules":["Use used to + verb for past habits or states that are no longer true."],"notes":["Used to has no present form. Be used to + -ing means \"be accustomed to\" (a different structure)."],"level":"B2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["I used to play football every day.","She didn\u0027t use to like coffee.","Did you use to live in Almaty?"],"title":"Used to"},{"quiz":[{"q":"Students ___ run in the corridor. (prohibited)","e":"mustn\u0027t","a":"mustn\u0027t"},{"q":"She ___ get up early on weekdays. (obligation)","e":"has to","a":"has to"},{"q":"You ___ pay, it\u0027s free. (not necessary)","e":"don\u0027t have to","a":"don\u0027t have to"},{"q":"Yesterday I ___ finish the report.","e":"had to","a":"had to"},{"q":"You ___ be quiet in the library.","e":"must","a":"must"},{"q":"___ you ___ work on Sundays?","e":"Do you have to","a":"Do you have to"}],"forms":["must + V | have/has to + V | mustn\u0027t + V | don\u0027t/doesn\u0027t have to + V"],"takeaway":"Must expresses strong obligation or logical conclusion (personal). Have to expresses external obligation (rules).","rules":["Must expresses strong obligation or logical conclusion (personal). Have to expresses external obligation (rules).","Mustn\u0027t = prohibition. Don\u0027t have to = it is not necessary."],"notes":["Past of must is had to."],"level":"B2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["You must do your homework.","I have to wear a uniform at school.","You mustn\u0027t smoke here.","You don\u0027t have to come tomorrow."],"title":"Modal verbs (Must/Have to)"},{"quiz":[{"q":"Take an umbrella. It ___ rain.","e":"may/might","a":["may","might"]},{"q":"___ I ask a question? (formal)","e":"May","a":"May"},{"q":"He ___ be late. (not sure)","e":"might","a":"might"},{"q":"She ___ not come. (possible)","e":"may/might","a":["may","might"]},{"q":"They ___ have left already.","e":"might","a":"might"},{"q":"___ I use your phone?","e":"May","a":"May"}],"forms":["may/might + V | may/might not + V"],"takeaway":"May and might express possibility. Might is less sure. May is also used for formal permission.","rules":["May and might express possibility. Might is less sure. May is also used for formal permission."],"notes":["Might have + V3 = possibility in the past: He might have forgotten."],"level":"B2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["It may rain tomorrow.","She might be at home.","May I come in?"],"title":"Modal verbs (May/Might)"},{"quiz":[{"q":"By tomorrow I ___ (finish).","e":"will have finished","a":"will have finished"},{"q":"She ___ (leave) by 6.","e":"will have left","a":"will have left"},{"q":"By next year we ___ (move).","e":"will have moved","a":"will have moved"},{"q":"___ he ___ (graduate) by June?","e":"Will he have graduated","a":"Will he have graduated"},{"q":"They ___ (not/arrive) by noon.","e":"won\u0027t have arrived","a":"won\u0027t have arrived"},{"q":"By 10 p.m. I ___ (do) all my work.","e":"will have done","a":"will have done"}],"forms":["will have + V3"],"takeaway":"Use Future Perfect for an action that will be completed before a point in the future.","rules":["Use Future Perfect for an action that will be completed before a point in the future."],"notes":["Signal words: by, by the time, by then."],"level":"B2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["By 2030 I will have finished university.","She will have left by the time you arrive.","Will they have finished by Friday?"],"title":"Future perfect"},{"quiz":[{"q":"At 9 tomorrow I ___ (work).","e":"will be working","a":"will be working"},{"q":"This time next week we ___ (lie) on the beach.","e":"will be lying","a":"will be lying"},{"q":"___ you ___ (use) your laptop?","e":"Will you be using","a":"Will you be using"},{"q":"She ___ (not/study) at that time.","e":"won\u0027t be studying","a":"won\u0027t be studying"},{"q":"At noon they ___ (travel).","e":"will be travelling","a":"will be travelling"},{"q":"Don\u0027t call at 7, I ___ (cook).","e":"will be cooking","a":"will be cooking"}],"forms":["will be + V-ing"],"takeaway":"Use Future Continuous for an action in progress at a certain moment in the future.","rules":["Use Future Continuous for an action in progress at a certain moment in the future."],"notes":["Also for polite questions about plans: Will you be coming?"],"level":"B2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["This time tomorrow I will be flying to Dubai.","At 8 she will be sleeping.","Will you be using the car tonight?"],"title":"Future Continuous"},{"quiz":[{"q":"I was born ___ 1998.","e":"in","a":"in"},{"q":"See you ___ Friday.","e":"on","a":"on"},{"q":"The class starts ___ 8:30.","e":"at","a":"at"},{"q":"The book is ___ the table.","e":"on","a":"on"},{"q":"He is ___ school now.","e":"at","a":"at"},{"q":"She walks ___ the park every day.","e":"through","a":"through"}],"forms":["at 5 / on Monday / in May | in the box / on the table / at school"],"takeaway":"Prepositions of time: at (clock time), on (days, dates), in (months, years, seasons).","rules":["Prepositions of time: at (clock time), on (days, dates), in (months, years, seasons).","Prepositions of place: in (inside), on (surface), at (point), under, behind, between, next to.","Prepositions of direction: to, into, from, through, across."],"notes":["Say at the weekend (UK), in the morning, at night."],"level":"B2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["The lesson starts at 9 on Monday.","She was born in 2005 in Astana.","The cat is under the table."],"title":"Prepositions"},{"quiz":[{"q":"Listen ___ me carefully.","e":"to","a":"to"},{"q":"She is looking ___ the photo.","e":"at","a":"at"},{"q":"We agree ___ you.","e":"with","a":"with"},{"q":"It depends ___ you.","e":"on","a":"on"},{"q":"They arrived ___ Almaty.","e":"in","a":"in"},{"q":"I am waiting ___ my friend.","e":"for","a":"for"}],"forms":["depend on | listen to | wait for | look at | think about | believe in | arrive in/at | ask for | apologize for | agree with"],"takeaway":"Many verbs need a fixed preposition after them. Learn them together with the verb.","rules":["Many verbs need a fixed preposition after them. Learn them together with the verb."],"notes":["Arrive in a city/country; arrive at a small place (the station)."],"level":"B2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["It depends on the weather.","I am waiting for the bus.","He apologized for being late."],"title":"Verbs with prepositions"},{"quiz":[{"q":"She ___ her coat. (put on)","e":"put on","a":"put on"},{"q":"Please ___ your shoes. (take off)","e":"take off","a":"take off"},{"q":"I am ___ my keys. (look for)","e":"looking for","a":"looking for"},{"q":"He ___ smoking last year. (give up)","e":"gave up","a":"gave up"},{"q":"Let\u0027s ___ the answer. (find out)","e":"find out","a":"find out"},{"q":"I ___ at 7 every day. (get up)","e":"get up","a":"get up"}],"forms":["give up | turn on/off | look for | look after | put on | take off | find out | get up | come back | set up"],"takeaway":"A phrasal verb = verb + particle (up, off, out, in, on, away). It often has a special meaning.","rules":["A phrasal verb = verb + particle (up, off, out, in, on, away). It often has a special meaning.","Separable: the object can go between (turn the light on / turn it on). Inseparable: the object goes after (look after children)."],"notes":["Pronouns go in the middle of separable verbs: turn it off (not \"turn off it\")."],"level":"B2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["I gave up smoking.","Please turn off the TV.","She looks after her little brother."],"title":"Phrasal verbs"},{"quiz":[{"q":"a ___ ___ house (old / big)","e":"big old","a":"big old"},{"q":"a ___ ___ dress (red / lovely)","e":"lovely red","a":"lovely red"},{"q":"a ___ ___ bag (leather / black)","e":"black leather","a":"black leather"},{"q":"an ___ ___ film (French / old)","e":"old French","a":"old French"},{"q":"a ___ ___ cat (small / white)","e":"small white","a":"small white"},{"q":"a ___ ___ table (wooden / round)","e":"round wooden","a":"round wooden"}],"forms":["opinion - size - age - shape - colour - origin - material - noun"],"takeaway":"When several adjectives describe a noun, they follow a fixed order: opinion, size, age, shape, colour, origin, material, purpose.","rules":["When several adjectives describe a noun, they follow a fixed order: opinion, size, age, shape, colour, origin, material, purpose."],"notes":["Usually no more than three adjectives are used together."],"level":"B2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["a beautiful big old round brown wooden table","a lovely small red car","an interesting old Italian book"],"title":"Order of adjectives"},{"quiz":[{"q":"I can\u0027t find my keys ___ . (anywhere / somewhere)","e":"anywhere","a":"anywhere"},{"q":"___ called you. (someone / anyone)","e":"Someone","a":"Someone"},{"q":"There is ___ in the fridge. (nothing / anything)","e":"nothing","a":"nothing"},{"q":"Do you want ___ to drink?","e":"something","a":"something"},{"q":"___ knows the answer. (No one / Anyone)","e":"No one","a":"No one"},{"q":"___ is ready. (Everything)","e":"Everything","a":"Everything"}],"forms":["someone, anyone, no one, everyone | something, anything, nothing, everything | somewhere, anywhere, nowhere, everywhere"],"takeaway":"Some- is used in positive sentences and offers; any- in negatives and questions; no- gives a negative meaning; every- means all.","rules":["Some- is used in positive sentences and offers; any- in negatives and questions; no- gives a negative meaning; every- means all.","They combine with -one/-body (people), -thing (things), -where (places)."],"notes":["Verbs after everyone/someone are singular: Everyone is here."],"level":"B2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["Someone is knocking at the door.","I don\u0027t know anything about it.","There is nothing in the box.","Everybody likes holidays."],"title":"Indefinite pronouns"},{"quiz":[{"q":"Prices ___ (rise) steadily this year.","e":"are rising","a":"are rising"},{"q":"He ___ (always/borrow) my pens!","e":"is always borrowing","a":"is always borrowing"},{"q":"The film ___ (start) at 8 p.m. tomorrow.","e":"starts","a":"starts"},{"q":"I ___ (wait) here since noon, and nobody ___ (come) yet.","e":"have been waiting, has come","a":"have been waiting, has come"},{"q":"In this scene the hero ___ (open) the door and ___ (see) a stranger.","e":"opens, sees","a":"opens, sees"},{"q":"She ___ (have) dinner, so she can\u0027t talk now.","e":"is having","a":"is having"}],"forms":["V/V-s | am/is/are + V-ing | have/has + V3 | have/has been + V-ing"],"takeaway":"Present Simple: habits, facts, timetables, narration (and reviews or jokes in the \"historic present\").","rules":["Present Simple: habits, facts, timetables, narration (and reviews or jokes in the \"historic present\").","Present Continuous: actions in progress, temporary situations, changing trends, and annoying habits with always.","Present Perfect and Present Perfect Continuous connect the past with the present (result, experience, duration)."],"notes":["State verbs (know, believe, belong, need) normally avoid continuous forms, but some change meaning: I am thinking about it / I think it\u0027s right."],"level":"C1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["The train leaves at 7.15. (timetable)","She is always losing her keys. (annoyance)","The population is rising rapidly. (trend)","I have been revising for hours; I have covered six units."],"title":"Tenses with Present meaning"},{"quiz":[{"q":"The film was so ___ that we fell asleep. (bore)","e":"boring","a":"boring"},{"q":"I was ___ by the news. (shock)","e":"shocked","a":"shocked"},{"q":"___ the letter, she cried. (read)","e":"Reading/Having read","a":["Reading","Having read"]},{"q":"The cars ___ in the street belong to my neighbours. (park)","e":"parked","a":"parked"},{"q":"The man ___ next to me is a doctor. (sit)","e":"sitting","a":"sitting"},{"q":"___ tired, he went to bed early. (feel)","e":"Feeling","a":"Feeling"}],"forms":["V-ing clause (active) | V3 clause (passive) | Having + V3 (earlier action)"],"takeaway":"Present participle (V-ing) has an active meaning: a boring lecture. Past participle (V3) has a passive or completed meaning: a bored student.","rules":["Present participle (V-ing) has an active meaning: a boring lecture. Past participle (V3) has a passive or completed meaning: a bored student.","Participle clauses shorten sentences: Walking home, I met Ali (= While I was walking home). Having finished, she left (= After she had finished).","The subject of the participle clause must be the same as the subject of the main clause, otherwise it is a dangling participle (error)."],"notes":["Wrong: Walking down the street, the sun was hot. Right: Walking down the street, I felt the sun was hot."],"level":"C1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["The woman standing at the door is my aunt.","Written in 1920, the book is still popular.","Having read the instructions, he started the engine.","Not knowing what to say, she kept silent."],"title":"Participles"},{"quiz":[{"q":"He suggested ___ (go) by train.","e":"going","a":"going"},{"q":"She refused ___ (help).","e":"to help","a":"to help"},{"q":"I forgot ___ (post) the letter, so it is still here.","e":"to post","a":"to post"},{"q":"He is good at ___ (solve) problems.","e":"solving","a":"solving"},{"q":"They managed ___ (finish) on time.","e":"to finish","a":"to finish"},{"q":"I regret ___ (tell) her the truth; it hurt her.","e":"telling","a":"telling"}],"forms":["enjoy + V-ing | decide + to V | stop + V-ing (quit) / stop + to V (pause in order to)"],"takeaway":"Verbs followed by gerund (V-ing): enjoy, avoid, finish, suggest, mind, keep, consider, deny, risk, admit.","rules":["Verbs followed by gerund (V-ing): enjoy, avoid, finish, suggest, mind, keep, consider, deny, risk, admit.","Verbs followed by to-infinitive: decide, hope, plan, promise, refuse, manage, afford, want, seem, expect, agree.","Some verbs take both with a change of meaning: stop (stop smoking / stop to smoke), remember, forget, try, regret, go on.","After prepositions, always use a gerund: interested in learning. Modal verbs take the bare infinitive."],"notes":["Try doing = experiment; try to do = make an effort."],"level":"C1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["She avoids talking about it.","We decided to leave early.","I remember locking the door. (memory of the action)","Remember to lock the door. (do not forget)"],"title":"Infinitive and Gerund"},{"quiz":[{"q":"Rewrite: I have never seen such a view.","e":"Never have I seen such a view.","a":"Never have I seen such a view."},{"q":"Rewrite: She not only sings but also dances.","e":"Not only does she sing, but she also dances.","a":"Not only does she sing, but she also dances."},{"q":"Rewrite: We had hardly sat down when the phone rang.","e":"Hardly had we sat down when the phone rang.","a":"Hardly had we sat down when the phone rang."},{"q":"\"Will it rain?\" \"I think ___.\" (substitution)","e":"so","a":"so"},{"q":"I like the blue shirt, not the red ___.","e":"one","a":"one"},{"q":"Seldom ___ he (visit) us.","e":"does he visit","a":"does he visit"}],"forms":["Never/Rarely/Seldom/Hardly + auxiliary + subject + V | Not only ... but also | So + adj + auxiliary + subject"],"takeaway":"Inversion: after negative or restrictive adverbials at the start of a sentence, the auxiliary comes before the subject (Never have I seen..., Hardly had he left when..., Not only did she...).","rules":["Inversion: after negative or restrictive adverbials at the start of a sentence, the auxiliary comes before the subject (Never have I seen..., Hardly had he left when..., Not only did she...).","Ellipsis omits words that can be understood: She can sing and (she can) dance.","Substitution replaces words: do so, one/ones, so, not (I think so / I hope not)."],"notes":["Inversion is formal and emphatic: use it in writing and speeches."],"level":"C1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["Never have I felt so tired.","Not only did he lie, but he also stole the money.","Hardly had we arrived when it started to rain.","\"Are you coming?\" \"I hope so.\""],"title":"Inversion, Ellipsis, Substitution"},{"quiz":[{"q":"If I ___ (have) more time, I would learn Japanese.","e":"had","a":"had"},{"q":"If they ___ (study) harder, they would have passed.","e":"had studied","a":"had studied"},{"q":"If you heat water to 100 C, it ___ (boil).","e":"boils","a":"boils"},{"q":"___ I known, I would have helped. (Had)","e":"Had","a":"Had"},{"q":"She will come ___ you invite her. (as long as/unless)","e":"as long as","a":"as long as"},{"q":"If I ___ (be) you, I wouldn\u0027t go.","e":"were","a":"were"}],"forms":["0: if + Present, Present | 1: if + Present, will | 2: if + V2, would + V | 3: if + had V3, would have V3"],"takeaway":"Zero: general truths (If you heat ice, it melts). First: real future (If it rains, we will stay home).","rules":["Zero: general truths (If you heat ice, it melts). First: real future (If it rains, we will stay home).","Second: unreal or unlikely present/future (If I were rich, I would travel). Third: unreal past (If I had studied, I would have passed).","Mixed: If I had taken the job, I would be rich now.","Formal alternatives: Unless (= if not), provided/providing that, as long as, Should you need..., Were I you..., Had I known...."],"notes":["In formal English use were for all persons in the second conditional: If he were here..."],"level":"C1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["If I were you, I would apologize.","If she had left earlier, she would have caught the train.","Had I known, I would have called you.","Unless you hurry, you will miss the bus."],"title":"Conditional Clauses"},{"quiz":[{"q":"He was out of breath. He ___ (run).","e":"had been running","a":"had been running"},{"q":"We ___ (wait) for two hours when she arrived.","e":"had been waiting","a":"had been waiting"},{"q":"___ you ___ (sleep) long before the phone rang?","e":"Had you been sleeping","a":"Had you been sleeping"},{"q":"The ground was wet; it ___ (rain).","e":"had been raining","a":"had been raining"},{"q":"She ___ (not/work) long when the boss came.","e":"hadn\u0027t been working","a":"hadn\u0027t been working"},{"q":"They ___ (live) there for ten years before they moved.","e":"had been living","a":"had been living"}],"forms":["had been + V-ing"],"takeaway":"Use Past Perfect Continuous for a longer action that was in progress before another past action or moment, stressing duration or its visible result.","rules":["Use Past Perfect Continuous for a longer action that was in progress before another past action or moment, stressing duration or its visible result."],"notes":["Compare: Past Perfect shows completion; Past Perfect Continuous shows process."],"level":"C1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["She was tired because she had been working all day.","They had been waiting for an hour when the bus finally came.","How long had you been studying before the exam?"],"title":"Past Perfect Continuous"},{"quiz":[{"q":"\"I live in Astana.\" - He said he ___ in Astana.","e":"lived","a":"lived"},{"q":"\"We have seen it.\" - They said they ___ it.","e":"had seen","a":"had seen"},{"q":"\"I will call.\" - She said she ___.","e":"would call","a":"would call"},{"q":"\"I can swim.\" - He said he ___ swim.","e":"could","a":"could"},{"q":"\"I am working.\" - She said she ___ .","e":"was working","a":"was working"},{"q":"\"I must go.\" - He said he ___ go.","e":"had to","a":"had to"}],"forms":["said that + Past Simple | said that + Past Perfect | said that + would"],"takeaway":"After a reporting verb in the past (said, told, asked), the verb in the subordinate clause usually moves one step back in time.","rules":["After a reporting verb in the past (said, told, asked), the verb in the subordinate clause usually moves one step back in time.","Present Simple becomes Past Simple; Present Continuous - Past Continuous; Present Perfect and Past Simple - Past Perfect; will - would; can - could; may - might; must - had to.","No change is needed when the statement is still true or a general fact: The teacher said that the Earth goes round the Sun."],"notes":["Time words shift: now - then, today - that day, tomorrow - the next day, yesterday - the day before."],"level":"C1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["\"I am tired.\" - She said she was tired.","\"I have finished.\" - He said he had finished.","\"I will help.\" - She promised she would help."],"title":"Sequence of tenses"},{"quiz":[{"q":"You ___ (not/eat) so much sugar.","e":"shouldn\u0027t eat","a":"shouldn\u0027t eat"},{"q":"___ I open the window?","e":"Shall","a":"Shall"},{"q":"I wasn\u0027t there. I ___ (go) with you.","e":"should have gone","a":"should have gone"},{"q":"It\u0027s late. They ___ be home by now.","e":"should","a":"should"},{"q":"He insisted that she ___ (apologize).","e":"(should) apologize","a":["(should) apologize","apologize","should apologize"]},{"q":"You ___ have told me earlier.","e":"should","a":"should"}],"forms":["should + V | shouldn\u0027t + V | should have + V3 | Shall I/we + V?"],"takeaway":"Should/ought to: advice and mild obligation (You should rest). Shall: offers and suggestions with I/we (Shall I help you?), and formal rules (The tenant shall pay rent).","rules":["Should/ought to: advice and mild obligation (You should rest). Shall: offers and suggestions with I/we (Shall I help you?), and formal rules (The tenant shall pay rent).","Should have + V3 = a criticism or regret about the past (You should have called). Should + V can also mean probability (They should be here by now)."],"notes":["Should is also used after suggest, insist, demand: I suggest that she should wait."],"level":"C1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["You should see a doctor.","Shall we go to the cinema?","He should have apologized.","It\u0027s essential that he be on time. (subjunctive)"],"title":"Modal Verbs (Shall/Should)"},{"quiz":[{"q":"___ you open the window, please? (polite)","e":"Would","a":"Would"},{"q":"In winter my grandfather ___ tell stories. (past habit)","e":"would","a":"would"},{"q":"The door ___ open, however hard I pushed. (refusal)","e":"wouldn\u0027t","a":"wouldn\u0027t"},{"q":"I ___ help you, I promise.","e":"will","a":"will"},{"q":"She said she ___ be late.","e":"would","a":"would"},{"q":"___ you mind waiting?","e":"Would","a":"Would"}],"forms":["will + V | would + V | would have + V3"],"takeaway":"Will: predictions, promises, spontaneous decisions, willingness, habits (He will sit for hours).","rules":["Will: predictions, promises, spontaneous decisions, willingness, habits (He will sit for hours).","Would: polite requests (Would you mind...?), past habits (We would play there every day), hypothetical situations, and future in the past.","Won\u0027t/wouldn\u0027t can express refusal: The car won\u0027t start. He wouldn\u0027t listen."],"notes":["Would is more polite and less direct than will."],"level":"C1","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["Would you pass me the salt, please?","When we were kids, we would swim every summer.","He wouldn\u0027t tell me the truth.","That would be nice."],"title":"Modal verbs (Will/Would)"},{"quiz":[{"q":"\"Are you ready?\" - She asked ___ I ___ ready.","e":"if/whether, was","a":["if","whether, was"]},{"q":"\"Don\u0027t touch it!\" - He told me ___ it.","e":"not to touch","a":"not to touch"},{"q":"\"What time is it?\" - He asked ___ .","e":"what time it was","a":"what time it was"},{"q":"\"I didn\u0027t take the money.\" - He denied ___ the money.","e":"taking","a":"taking"},{"q":"\"Sit down, please.\" - She asked me ___ down.","e":"to sit","a":"to sit"},{"q":"\"Why are you late?\" - The teacher asked why I ___ late.","e":"was","a":"was"}],"forms":["asked + if/whether + S + V | told + O + to V | suggested + V-ing / that + S + (should) V"],"takeaway":"Statements: He said (that) + backshifted clause. Questions: She asked if/whether (yes/no) or + wh-word with statement word order.","rules":["Statements: He said (that) + backshifted clause. Questions: She asked if/whether (yes/no) or + wh-word with statement word order.","Commands/requests use an infinitive: He told me to sit down. He asked me not to be late.","Reporting verbs add meaning: suggest, warn, advise, promise, admit, deny, insist, remind, offer, refuse."],"notes":["Say has no object (say that); tell has one (tell him that)."],"level":"C2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["\"Where do you live?\" - He asked me where I lived.","\"Do you like tea?\" - She asked if I liked tea.","\"Close the door.\" - He told me to close the door.","\"Let\u0027s go home.\" - She suggested going home."],"title":"Indirect speech"},{"quiz":[{"q":"By next May he ___ (teach) for ten years.","e":"will have been teaching","a":"will have been teaching"},{"q":"By noon we ___ (drive) for six hours.","e":"will have been driving","a":"will have been driving"},{"q":"___ she ___ (live) here for a year by then?","e":"Will she have been living","a":"Will she have been living"},{"q":"By 2030 they ___ (build) the bridge for a decade.","e":"will have been building","a":"will have been building"},{"q":"I ___ (not/work) long by the time you arrive.","e":"won\u0027t have been working","a":"won\u0027t have been working"},{"q":"By Friday I ___ (learn) English for exactly 3 years.","e":"will have been learning","a":"will have been learning"}],"forms":["will have been + V-ing"],"takeaway":"Use Future Perfect Continuous to say how long an action will have been in progress by a certain future moment.","rules":["Use Future Perfect Continuous to say how long an action will have been in progress by a certain future moment."],"notes":["Signal words: by, by the time, for + period."],"level":"C2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["By June I will have been working here for five years.","By the time she arrives, we will have been waiting for two hours.","How long will you have been studying by then?"],"title":"Future Perfect Continuous"},{"quiz":[{"q":"At 6 p.m. he ___ (cook) dinner.","e":"will be cooking","a":"will be cooking"},{"q":"By 6 p.m. he ___ (cook) for two hours.","e":"will have been cooking","a":"will have been cooking"},{"q":"Next summer we ___ (travel) around Europe.","e":"will be travelling","a":"will be travelling"},{"q":"By July I ___ (study) here for a year.","e":"will have been studying","a":"will have been studying"},{"q":"At noon she ___ (sleep).","e":"will be sleeping","a":"will be sleeping"},{"q":"By midnight they ___ (dance) for six hours.","e":"will have been dancing","a":"will have been dancing"}],"forms":["will be + V-ing | will have been + V-ing"],"takeaway":"Future Continuous: an action in progress at a point in the future. Future Perfect Continuous: duration of an action up to a point in the future.","rules":["Future Continuous: an action in progress at a point in the future. Future Perfect Continuous: duration of an action up to a point in the future."],"notes":["Look for for + period and by + time: they signal Future Perfect Continuous."],"level":"C2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["At 9 tomorrow I will be working. (in progress then)","At 9 tomorrow I will have been working for four hours. (duration up to then)","This time next year she will be living in London."],"title":"Fut. Cont. vs. Fut. Perf. Cont."},{"quiz":[{"q":"I ___ (watch) TV when you called.","e":"was watching","a":"was watching"},{"q":"The film ___ (already/start) when we arrived.","e":"had already started","a":"had already started"},{"q":"He ___ (study) for hours before he took a break.","e":"had been studying","a":"had been studying"},{"q":"We ___ (visit) Rome in 2015.","e":"visited","a":"visited"},{"q":"She ___ (play) piano every day as a girl. (habit)","e":"used to play / would play","a":["used to play","would play"]},{"q":"After they ___ (eat), they left.","e":"had eaten","a":"had eaten"}],"forms":["V2 | was/were + V-ing | had + V3 | had been + V-ing"],"takeaway":"Past Simple: finished actions. Past Continuous: in progress. Past Perfect: before another past action. Past Perfect Continuous: duration before a past moment.","rules":["Past Simple: finished actions. Past Continuous: in progress. Past Perfect: before another past action. Past Perfect Continuous: duration before a past moment.","Used to / would: past habits. Present Perfect can also refer to the past when the time is not specified."],"notes":["Choose the tense by the relation between events, not only by the time word."],"level":"C2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["He left at six. / He was leaving when I called.","When I got there, he had already left.","She was exhausted: she had been running for an hour."],"title":"Tenses with Past meaning"},{"quiz":[{"q":"We ___ (meet) the director at 5. (arranged)","e":"are meeting","a":"are meeting"},{"q":"The bus ___ (leave) at 7:15. (timetable)","e":"leaves","a":"leaves"},{"q":"I\u0027ll call you as soon as I ___ (arrive).","e":"arrive","a":"arrive"},{"q":"This time tomorrow I ___ (fly) to Rome.","e":"will be flying","a":"will be flying"},{"q":"By next year he ___ (graduate).","e":"will have graduated","a":"will have graduated"},{"q":"Look at those clouds! It ___ (rain).","e":"is going to rain","a":"is going to rain"}],"forms":["will V | am/is/are going to V | will be V-ing | will have V3 | will have been V-ing"],"takeaway":"Will: predictions, spontaneous decisions. Be going to: plans, evidence. Present Continuous: arranged plans. Present Simple: timetables.","rules":["Will: predictions, spontaneous decisions. Be going to: plans, evidence. Present Continuous: arranged plans. Present Simple: timetables.","Future Continuous: action in progress then. Future Perfect: completed by a future time. Future Perfect Continuous: duration by a future time.","Be about to: very near future. Be to: official arrangements."],"notes":["In time clauses (when, after, as soon as, until) use the Present tense, not will: I will call you when I arrive."],"level":"C2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["I\u0027m meeting her at 6. (arrangement)","The plane takes off at 9. (timetable)","The film is about to start.","By 2030 they will have built a new city."],"title":"Tenses with future meaning"},{"quiz":[{"q":"The work ___ (finish) before noon.","e":"had been finished","a":"had been finished"},{"q":"The letters ___ (not/send) by Friday.","e":"hadn\u0027t been sent","a":"hadn\u0027t been sent"},{"q":"___ the window ___ (break) before you came?","e":"Had the window been broken","a":"Had the window been broken"},{"q":"The cake ___ (eat) when we got home.","e":"had been eaten","a":"had been eaten"},{"q":"By 2010 the bridge ___ (open).","e":"had been opened","a":"had been opened"},{"q":"All the tickets ___ (sell) by the time I called.","e":"had been sold","a":"had been sold"}],"forms":["had been + V3"],"takeaway":"Use Past Perfect passive for an action that had been done to someone or something before a past moment.","rules":["Use Past Perfect passive for an action that had been done to someone or something before a past moment."],"notes":["Active: They had repaired the road. Passive: The road had been repaired."],"level":"C2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["When I arrived, the tickets had already been sold.","The house had been built before the war.","Had the letter been sent before you left?"],"title":"Past perfect passive"},{"quiz":[{"q":"The bridge ___ (repair) at the moment.","e":"is being repaired","a":"is being repaired"},{"q":"The cars ___ (wash) when I arrived.","e":"were being washed","a":"were being washed"},{"q":"A new museum ___ (build) now.","e":"is being built","a":"is being built"},{"q":"The documents ___ (check) at present.","e":"are being checked","a":"are being checked"},{"q":"She ___ (interview) when I called.","e":"was being interviewed","a":"was being interviewed"},{"q":"The windows ___ (clean) right now.","e":"are being cleaned","a":"are being cleaned"}],"forms":["am/is/are + being + V3 | was/were + being + V3"],"takeaway":"Present Continuous passive: an action in progress being done to something now. Past Continuous passive: in progress at a past moment.","rules":["Present Continuous passive: an action in progress being done to something now. Past Continuous passive: in progress at a past moment."],"notes":["Do not confuse: The house is built (state) and The house is being built (process now)."],"level":"C2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["The road is being repaired.","The room was being cleaned when I came in.","A new school is being built in our district."],"title":"Present/Past Continuous Passive"},{"quiz":[{"q":"The project ___ (complete) by June.","e":"will have been completed","a":"will have been completed"},{"q":"All the tickets ___ (sell) by tomorrow.","e":"will have been sold","a":"will have been sold"},{"q":"The documents ___ (sign) by noon.","e":"will have been signed","a":"will have been signed"},{"q":"___ the room ___ (clean) by 5?","e":"Will the room have been cleaned","a":"Will the room have been cleaned"},{"q":"The bridge ___ (not/finish) by 2030.","e":"won\u0027t have been finished","a":"won\u0027t have been finished"},{"q":"By Monday the goods ___ (deliver).","e":"will have been delivered","a":"will have been delivered"}],"forms":["will have been + V3"],"takeaway":"Use Future Perfect passive for an action that will have been done by a future moment.","rules":["Use Future Perfect passive for an action that will have been done by a future moment."],"notes":["Active: They will have built a new school by 2027. Passive: A new school will have been built by 2027."],"level":"C2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["The report will have been finished by Friday.","By next year the road will have been repaired.","Will the work have been completed by then?"],"title":"Future perfect passive"},{"quiz":[{"q":"Fill in (write, Present Perfect Continuous): I ___ for an hour.","e":"have been writing","a":"have been writing"},{"q":"Fill in (go, Past Perfect): He ___ before we came.","e":"had gone","a":"had gone"},{"q":"Fill in (work, Future Continuous): At 9 I ___.","e":"will be working","a":"will be working"},{"q":"Fill in (read, Future Perfect): By Friday she ___ the book.","e":"will have read","a":"will have read"},{"q":"Fill in (play, Past Continuous): They ___ at 5.","e":"were playing","a":"were playing"},{"q":"Fill in (say, Future in the Past): She said she ___ . (come)","e":"would come","a":"would come"}],"forms":["Present: V | am/is/are V-ing | have V3 | have been V-ing","Past: V2 | was/were V-ing | had V3 | had been V-ing","Future: will V | will be V-ing | will have V3 | will have been V-ing","Future in the Past: would V | would be V-ing | would have V3 | would have been V-ing"],"takeaway":"English has 4 aspects (Simple, Continuous, Perfect, Perfect Continuous) in 3 times (Present, Past, Future) = 12 active tenses; with Future in the Past (would) there are 16 forms in the traditional table.","rules":["English has 4 aspects (Simple, Continuous, Perfect, Perfect Continuous) in 3 times (Present, Past, Future) = 12 active tenses; with Future in the Past (would) there are 16 forms in the traditional table.","Simple: fact/habit. Continuous: in progress. Perfect: completed before a point/result. Perfect Continuous: duration up to a point."],"notes":["Learn one verb (e.g., write) in all 16 forms and check yourself using the table."],"level":"C2","spec":"Grammar · правило, формулы, примеры и 6 упражнений","ex":["She works / is working / has worked / has been working.","She worked / was working / had worked / had been working.","She will work / will be working / will have worked / will have been working.","She said she would work / would be working / would have worked / would have been working."],"title":"16 English tenses"}];
